/* Ruang Hari — vanilla JavaScript. No frontend framework. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',check:'<rect x="4" y="3" width="16" height="18" rx="4"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M4 3h13a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3zm0 14h16M8 7h7M8 10h5"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',settings:'<path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0v6l2 3H3l2-3zM10 21h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 5v14M16 5v14"/>',prev:'<path d="M5 5v14m14-14L7 12l12 7z"/>',next:'<path d="M19 5v14M5 5l12 7-12 7z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>'};
const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
function paintIcons(){ $$('[data-icon]').forEach(el=>el.innerHTML=ic(el.dataset.icon)); }
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const today=localDate(); const dateText=(s,options={day:'numeric',month:'long'})=>new Date(s+'T12:00:00').toLocaleDateString('id-ID',options);
let storageOK=true;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}function write(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{storageOK=false;toast('Penyimpanan penuh atau tidak tersedia. Ekspor data untuk cadangan.');return false}}
let localProfile=read('rh.profile',{name:'Ruang personal',bio:'Sedikit demi sedikit, hari lebih baik.',photo:''});
if(!localProfile||typeof localProfile.name!=='string')localProfile={name:'Ruang personal',bio:'Sedikit demi sedikit, hari lebih baik.',photo:''};
let state=read('rh.local',{tasks:[],journals:[]});
if(!Array.isArray(state.tasks)||!Array.isArray(state.journals))state={tasks:[],journals:[]};
let draftPhoto='',revealObserver=null,viewAnimation=null;
let view='home',selectedDate=today,filter='Semua',search='',inbox=read('rh.inbox',[]),notified=read('rh.notified',{});
let timerLeft=25*60,timerEnd=null,timerInterval=null,tracks=[],trackIndex=0,db=null,native=null;
const audio=$('#audio'); let lastSeek=0;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function recordNotification(title){inbox.unshift({title,date:new Date().toISOString()});inbox=inbox.slice(0,40);write('rh.inbox',inbox);$('#bell-dot').style.display='block';}
async function commit(next){if(!write('rh.local',next))return false;state=next;return true;}
function safePhoto(photo){return typeof photo==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(photo)?photo:''}
function avatarHTML(photo=localProfile.photo,name=localProfile.name){return safePhoto(photo)?`<img src="${photo}" alt="Foto profil">`:esc(Array.from(name.trim()||'R')[0].toUpperCase())}
function profile(){ $('#user-name').textContent=localProfile.name;$('#mode-label').textContent='Tersimpan di perangkat';$('.avatar').innerHTML=avatarHTML();$('#greeting').textContent=view==='home'?'YOUR DAY, YOUR OWN PACE':'MAKE ROOM FOR YOUR DAY';}
function setView(v){if(!titles[v]||v===view)return;view=v;render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){viewAnimation?.cancel();viewAnimation=$('main').animate([{opacity:.35,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,easing:'cubic-bezier(.2,.7,.2,1)'});}}
function observeReveals(){revealObserver?.disconnect();if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('revealed');revealObserver.unobserve(entry.target)}},{threshold:.08});$$('#content .panel, #content .schedule, #content .task-row').forEach((el,i)=>{if(el.getBoundingClientRect().top>=innerHeight-24){el.classList.add('scroll-reveal');el.style.setProperty('--reveal-delay',`${Math.min(i%3*65,130)}ms`);revealObserver.observe(el)}});}
const titles={home:['Hari ini,<br><span>lebih terarah.</span>','Ruang untuk rencana, cerita, dan jeda kecilmu.','Ringkasan'],tasks:['Satu tugas,<br><span>satu langkah.</span>','Beri tempat untuk hal-hal yang penting.','Tugas saya'],journal:['Cerita kecil,<br><span>berarti besar.</span>','Simpan apa yang kamu rasakan hari ini.','Jurnal harian'],music:['Ambil jeda.<br><span>Putar suasana.</span>','Lagu milikmu, untuk ritme harimu sendiri.','Musik'],settings:['Ruangmu,<br><span>caramu.</span>','Atur hal kecil untuk pengalaman yang nyaman.','Pengaturan']};
function musicCard(){const track=tracks[trackIndex];return `<section class="panel music-card ${audio.paused?'':'playing'}"><div class="section-head"><h2>Sound of the day</h2><button class="text-btn" data-action="upload" aria-label="Tambah musik">${ic('plus')}</button></div><div class="vinyl-wrap"><div class="vinyl"></div></div><h3 class="song-name">${track?esc(track.name):'A little pause'}</h3><p class="song-artist">${track?'KOLEKSI PERSONAL':'Pilih lagu dari perangkatmu'}</p><input class="seek" aria-label="Posisi lagu" type="range" min="0" max="100" value="${lastSeek}" ${track?'':'disabled'}><div class="player-controls"><button data-action="previous" aria-label="Lagu sebelumnya">${ic('prev')}</button><button class="play" data-action="play" aria-label="${audio.paused?'Putar':'Jeda'}">${ic(audio.paused?'play':'pause')}</button><button data-action="next" aria-label="Lagu berikutnya">${ic('next')}</button><button data-action="upload" aria-label="Tambahkan lagu">${ic('upload')}</button></div></section>`}
function taskPill(t){return `<div class="timeline-row"><span class="time">${esc(t.time)}</span><div class="task-pill ${t.category==='Personal'?'light':''} ${t.done?'done':''}"><button class="check ${t.done?'checked':''}" data-toggle="${esc(t.id)}" aria-label="${t.done?'Batalkan selesai':'Selesaikan'} ${esc(t.title)}">${t.done?'✓':''}</button><span class="title">${esc(t.title)}</span><button class="text-btn" data-edit-task="${esc(t.id)}" aria-label="Edit ${esc(t.title)}" style="color:inherit">↗</button></div></div>`}
function renderHome(){const tasks=state.tasks.filter(t=>t.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time)),done=tasks.filter(t=>t.done).length,pct=tasks.length?Math.round(done/tasks.length*100):0;const start=new Date(selectedDate+'T12:00:00');start.setDate(start.getDate()-((start.getDay()+6)%7));let week='';for(let i=0;i<7;i++){let d=new Date(start);d.setDate(start.getDate()+i);let str=localDate(d);week+=`<button class="day ${str===selectedDate?'active':''}" data-date="${str}"><span>${['MIN','SEN','SEL','RAB','KAM','JUM','SAB'][d.getDay()]}</span><b>${d.getDate()}</b></button>`}const journals=[...state.journals].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);
return `<div class="top-grid"><section class="schedule"><div class="section-head"><h2>Rencana harian <span class="tiny">/ ${String(tasks.length).padStart(2,'0')}</span></h2><input class="date-picker" type="date" aria-label="Pilih tanggal jadwal" value="${selectedDate}" id="schedule-date"></div><div class="week">${week}</div><div class="timeline">${tasks.length?tasks.map(taskPill).join(''):`<div class="empty"><strong>Masih ada ruang.</strong>Belum ada tugas pada tanggal ini.<br><button class="text-btn" data-action="add-task">Buat rencana pertama ↗</button></div>`}</div></section><section class="panel summary"><div class="section-head"><h2>Langkah hari ini</h2><span class="tiny">↗</span></div><div class="progress-value">${pct}<span>%</span></div><p>${done} dari ${tasks.length} tugas selesai</p><svg class="sparkline" viewBox="0 0 180 80"><path stroke="#d3d8cb" d="M0 65Q25 5 55 40T110 30T180 30"/><path d="M0 65Q25 65 35 38T80 40T125 25T180 25"/></svg><div class="legend-row"><span><i class="dot"></i>Selesai</span><b>${String(done).padStart(2,'0')}</b></div><div class="legend-row"><span><i class="dot gray"></i>Dalam rencana</span><b>${String(tasks.length-done).padStart(2,'0')}</b></div><div class="legend-row"><span><i class="dot pale"></i>Catatan hari ini</span><b>${String(state.journals.filter(j=>j.date===selectedDate).length).padStart(2,'0')}</b></div></section>${musicCard()}</div><div class="lower-grid"><section class="panel"><div class="section-head"><h2>Sepotong cerita</h2><button class="icon-btn" data-action="add-journal" aria-label="Tulis jurnal">${ic('plus')}</button></div><div class="notes-list">${journals.length?journals.map(j=>`<button class="note-item" data-edit-journal="${esc(j.id)}">${ic('book')}<div><b>${esc(j.title)}</b><small>${dateText(j.date)} · ${esc(j.mood)}</small></div><span>↗</span></button>`).join(''):`<div class="empty" style="padding:15px 0">Apa hal baik yang terjadi hari ini?<br><button class="text-btn" data-action="add-journal">Tulis cerita pertamamu ↗</button></div>`}</div></section><section class="panel focus-panel"><div class="focus-top"><span>FOCUS MODE</span>${ic('headphones')}</div><div class="focus-body"><div><h2>Sedikit lebih fokus.</h2><p>25 menit untuk satu hal yang berarti.</p></div><div class="timer" id="timer">${timerText()}</div></div><div class="focus-bottom"><button class="primary" data-action="timer" id="timer-button">${timerEnd?'Jeda fokus':'Mulai fokus'} ${ic('arrow')}</button><button class="secondary" data-action="timer-reset" aria-label="Atur ulang timer">↺</button><small>ONE THING AT A TIME.</small></div></section></div>`}
function renderTasks(){const tasks=state.tasks.filter(t=>(filter==='Semua'||(filter==='Selesai'?t.done:!t.done))&&t.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="filterbar"><input id="task-search" aria-label="Cari tugas" placeholder="Cari rencana…" value="${esc(search)}">${['Semua','Aktif','Selesai'].map(f=>`<button class="filter-chip ${f===filter?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="task-list">${tasks.length?tasks.map(t=>`<article class="task-row ${t.done?'done':''}"><button class="check ${t.done?'checked':''}" data-toggle="${esc(t.id)}" aria-label="Tandai ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-info"><b>${esc(t.title)}</b><small>${dateText(t.date)} · ${esc(t.time)}${t.remind?' · Pengingat aktif':''}</small></div><span class="tag">${esc(t.category)} · ${esc(t.priority)}</span><button class="icon-btn" data-edit-task="${esc(t.id)}" aria-label="Edit tugas">${ic('edit')}</button><button class="icon-btn danger" data-delete-task="${esc(t.id)}" aria-label="Hapus tugas">${ic('trash')}</button></article>`).join(''):`<div class="panel empty"><strong>${search?'Tidak ada hasil.':'Ruang untuk rencana baru.'}</strong>${search?'Coba kata lain.':'Tambahkan tugas pertamamu lewat tombol di atas.'}</div>`}</div>`}
function renderJournals(){return `<div class="journal-grid">${state.journals.length?[...state.journals].sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<article class="panel journal-card"><div class="section-head" style="margin:0"><small>${dateText(j.date)}</small><span class="tag">${esc(j.mood)}</span></div><h3>${esc(j.title)}</h3><p>${esc(j.body)}</p><div class="journal-actions"><button class="text-btn" data-edit-journal="${esc(j.id)}">Baca & edit ↗</button><button class="text-btn danger" data-delete-journal="${esc(j.id)}">Hapus</button></div></article>`).join(''):`<div class="panel empty" style="grid-column:1/-1"><strong>Setiap hari punya cerita.</strong>Mulai dengan satu hal yang kamu syukuri hari ini.<br><button class="text-btn" data-action="add-journal">Tulis jurnal ↗</button></div>`}</div>`}
function renderMusic(){return `<div class="music-layout">${musicCard()}<section class="panel"><div class="section-head"><h2>Koleksi personal <span class="tiny">/ ${tracks.length}</span></h2><button class="secondary" data-action="upload">${ic('plus')} Tambah lagu</button></div><div class="playlist">${tracks.length?tracks.map((t,i)=>`<div class="track-row ${i===trackIndex?'active':''}"><button class="icon-btn" data-track="${i}" aria-label="Putar ${esc(t.name)}">${ic(i===trackIndex&&!audio.paused?'pause':'play')}</button><div><b>${esc(t.name)}</b><small>Audio lokal · ${(t.blob.size/1048576).toFixed(1)} MB</small></div><button class="text-btn danger" data-delete-track="${i}" aria-label="Hapus lagu">${ic('trash')}</button></div>`).join(''):`<div class="empty"><strong>Ritme harimu dimulai di sini.</strong>Tambahkan MP3, M4A, OGG atau audio yang didukung perangkat.<br>Lagu disimpan pada perangkat ini, tidak diunggah ke server.</div>`}</div></section></div>`}
function renderSettings(){return `<div class="settings"><section class="panel profile-card"><div class="section-head"><h2>Profil personal</h2><span class="status-pill">HANYA DI PERANGKATMU</span></div><div class="profile-overview"><span class="avatar avatar-large">${avatarHTML()}</span><div class="profile-copy"><h3>${esc(localProfile.name)}</h3><p>${esc(localProfile.bio||'Ruang kecil untuk harimu.')}</p></div><button class="secondary" data-action="edit-profile">${ic('edit')} Ubah profil</button></div></section><section class="panel"><div class="section-head"><h2>Pengingat</h2><span class="tiny">LOCAL NOTIFICATIONS</span></div><div class="setting-row"><div><h3>Jangan lewatkan rencanamu.</h3><p>APK Android memakai notifikasi lokal terjadwal.<br>Versi web memerlukan halaman terbuka dan izin notifikasi.</p></div><button class="secondary" data-action="notify">Aktifkan</button></div></section><section class="panel"><h2 style="font-size:14px;font-weight:500">Data & privasi</h2><div class="setting-row"><div><h3>Simpan salinan pribadi.</h3><p>Tugas, jurnal, dan profil tersimpan di localStorage.<br>Ekspor sebagai cadangan, lalu impor di perangkat lain.</p></div><button class="secondary" data-action="export">Ekspor data ↗</button></div><button class="text-btn" data-action="import">Impor cadangan JSON ↗</button><p class="hint">${storageOK?'Penyimpanan perangkat aktif.':'Penyimpanan perangkat tidak tersedia; ekspor data sebelum menutup.'} Musik disimpan di IndexedDB karena ukuran berkasnya lebih besar. Menghapus data browser/aplikasi juga menghapus data lokal. Tidak ada sinkronisasi cloud.</p></section><section class="panel motion-note"><p class="eyebrow">DESIGNED TO FEEL A LITTLE LIGHTER</p><h3>Gerakan kecil. Ritme yang tenang.</h3><p class="hint">Panel muncul lembut saat di-scroll dan halaman bertransisi saat berpindah tab. Animasi mengikuti pengaturan kurangi gerakan di perangkatmu.</p></section><section class="panel"><p class="eyebrow">RUANG HARI · VERSION 1.1</p><p class="hint">HTML, CSS, JavaScript. Tanpa akun atau server. Ruang personal yang selalu dekat denganmu.</p></section></div>`}
function render(){profile();$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').innerHTML=view==='home'&&localProfile.name!=='Ruang personal'?`Halo, ${esc(localProfile.name)}.<br><span>Ini ruang harimu.</span>`:titles[view][0];$('#page-subtitle').textContent=titles[view][1];$('#crumb').textContent=titles[view][2].toUpperCase();$('#nav-count').textContent=state.tasks.filter(t=>!t.done).length;$('#add-task').innerHTML=ic('plus')+(view==='journal'?' Tulis cerita':view==='music'?' Tambah lagu':' Tugas baru');$('#add-task').style.display=view==='settings'?'none':'';$('#content').innerHTML=({home:renderHome,tasks:renderTasks,journal:renderJournals,music:renderMusic,settings:renderSettings})[view]();paintIcons();observeReveals();}
function openTask(id){const t=state.tasks.find(t=>t.id===id),f=$('#task-form');f.reset();f.elements.id.value=t?.id||'';for(const k of ['title','date','time','category','priority'])if(t)f.elements[k].value=t[k];if(!t){f.elements.date.value=selectedDate;let d=new Date(Date.now()+3600000);f.elements.time.value=d.toTimeString().slice(0,5)}f.elements.remind.checked=t?t.remind:true;$('#task-dialog-title').textContent=t?'Atur kembali rencanamu.':'Rencana kecil, hari baik.';$('#task-dialog').showModal();}
function openJournal(id){const j=state.journals.find(j=>j.id===id),f=$('#journal-form');f.reset();f.elements.id.value=j?.id||'';f.elements.date.value=today;if(j)for(const k of ['title','date','mood','body'])f.elements[k].value=j[k];$('#journal-dialog').showModal()}
$('#task-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),existing=state.tasks.find(t=>t.id===d.id);if(!d.title.trim())return;let task={id:d.id||uid(),title:d.title.trim(),date:d.date,time:d.time,category:d.category,priority:d.priority,remind:f.elements.remind.checked,done:existing?.done||false};if(await commit({...state,tasks:existing?state.tasks.map(t=>t.id===task.id?task:t):[...state.tasks,task]})){delete notified[task.id];write('rh.notified',notified);$('#task-dialog').close();render();await scheduleNative();toast('Rencana tersimpan. Satu langkah lebih dekat.');}});
$('#journal-form').addEventListener('submit',async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.title=d.title.trim();if(!d.title||!d.body.trim())return;const exists=state.journals.some(j=>j.id===d.id);d.id=d.id||uid();if(await commit({...state,journals:exists?state.journals.map(j=>j.id===d.id?d:j):[...state.journals,d]})){$('#journal-dialog').close();render();toast('Ceritamu tersimpan.')}});
async function enableNotifications(){try{if(native){const p=await native.requestPermissions();if(p.display!=='granted')return toast('Izin notifikasi belum diberikan. Aktifkan lewat pengaturan Android.');await scheduleNative();toast('Notifikasi Android aktif.')}else if('Notification'in window){const p=await Notification.requestPermission();toast(p==='granted'?'Notifikasi aktif selama halaman terbuka.':'Izin belum diberikan. Cek pengaturan browser.')}else toast('Browser ini tidak mendukung notifikasi sistem. Pengingat di halaman tetap aktif.')}catch{toast('Notifikasi belum tersedia. Periksa izin aplikasi.')}}
function nativeId(id){let n=0;for(let i=0;i<id.length;i++)n=(Math.imul(31,n)+id.charCodeAt(i))|0;return (n>>>0)%2147483646+1}
async function scheduleNative(){if(!native)return;try{if((await native.checkPermissions()).display!=='granted')return;const pending=await native.getPending();const taskPending=pending.notifications.filter(n=>n.id!==2147483647);if(taskPending.length)await native.cancel({notifications:taskPending});const notifications=state.tasks.filter(t=>t.remind&&!t.done&&new Date(t.date+'T'+t.time).getTime()>Date.now()).map(t=>({id:nativeId(t.id),title:'Waktunya untuk rencanamu',body:t.title,schedule:{at:new Date(t.date+'T'+t.time),allowWhileIdle:true},channelId:'daily-reminders'}));if(notifications.length)await native.schedule({notifications});}catch(e){toast('Pengingat Android gagal dijadwalkan. Periksa izin notifikasi.')}}
function checkReminders(){for(const t of state.tasks){let due=new Date(t.date+'T'+t.time).getTime();let fingerprint=t.date+t.time;if(t.remind&&!t.done&&due<=Date.now()&&due>Date.now()-86400000&&notified[t.id]!==fingerprint){notified[t.id]=fingerprint;write('rh.notified',notified);recordNotification(t.title);toast('Pengingat: '+t.title);if(!native&&'Notification'in window&&Notification.permission==='granted')try{new Notification('Ruang Hari · Pengingat',{body:t.title,tag:t.id})}catch{}}}}
function timerText(){let s=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):timerLeft;return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function updateTimer(){if(timerEnd&&Date.now()>=timerEnd){timerEnd=null;timerLeft=25*60;recordNotification('Sesi fokus selesai. Ambil jeda kecil.');toast('25 menit selesai. Saatnya ambil jeda.');if('Notification'in window&&Notification.permission==='granted'&&!native)try{new Notification('Sesi fokus selesai',{body:'Ambil jeda kecil, kamu sudah melangkah.'})}catch{}if(view==='home')render()}if($('#timer'))$('#timer').textContent=timerText();}
async function toggleTimer(){if(timerEnd){timerLeft=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerEnd=null;if(native)await native.cancel({notifications:[{id:2147483647}]});}else{timerEnd=Date.now()+timerLeft*1000;if(native&&(await native.checkPermissions()).display==='granted')await native.schedule({notifications:[{id:2147483647,title:'Sesi fokus selesai',body:'Ambil jeda kecil. Kamu sudah melangkah.',schedule:{at:new Date(timerEnd)},channelId:'daily-reminders'}]})}render()}
async function initMusic(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('ruang-hari-music',1);req.onupgradeneeded=()=>req.result.createObjectStore('tracks',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const items=await new Promise((resolve,reject)=>{const r=db.transaction('tracks').objectStore('tracks').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});tracks=items.map(t=>({...t,url:URL.createObjectURL(t.blob)}));if(tracks.length)audio.src=tracks[0].url;render()}catch{toast('Penyimpanan musik tidak tersedia; lagu hanya bertahan selama sesi.')}}
function storeTrack(track,remove=false){return new Promise((resolve,reject)=>{if(!db)return resolve();const tx=db.transaction('tracks','readwrite');const store=tx.objectStore('tracks');remove?store.delete(track.id):store.put({id:track.id,name:track.name,blob:track.blob});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
$('#music-files').addEventListener('change',async e=>{let count=0;for(const file of e.target.files){if(file.size>100*1048576){toast('Batas ukuran satu lagu 100 MB.');continue}const t={id:uid(),name:file.name.replace(/\.[^.]+$/,''),blob:file,url:URL.createObjectURL(file)};try{await storeTrack(t);tracks.push(t);count++}catch{URL.revokeObjectURL(t.url);toast('Ruang penyimpanan musik penuh.')}}if(!audio.getAttribute('src')&&tracks.length)audio.src=tracks[0].url;render();if(count)toast(`${count} lagu ditambahkan.`);e.target.value=''});
async function playTrack(i){if(!tracks.length){$('#music-files').click();return}if(i!==trackIndex||!audio.getAttribute('src')){trackIndex=(i+tracks.length)%tracks.length;audio.src=tracks[trackIndex].url;lastSeek=0}try{await audio.play()}catch{toast('Audio tidak dapat diputar. Coba format lain seperti MP3.')}render()}
async function playPause(){if(!tracks.length)return $('#music-files').click();if(audio.paused)await playTrack(trackIndex);else{audio.pause();render()}}
audio.addEventListener('timeupdate',()=>{lastSeek=audio.duration?audio.currentTime/audio.duration*100:0;$$('.seek').forEach(s=>s.value=lastSeek)});audio.addEventListener('ended',()=>playTrack((trackIndex+1)%tracks.length));audio.addEventListener('error',()=>toast('Format audio ini tidak didukung perangkat.'));
async function exportData(){const blob=new Blob([JSON.stringify({app:'ruang-hari',format:2,...state,profile:localProfile},null,2)],{type:'application/json'});const file=new File([blob],`ruang-hari-${today}.json`,{type:'application/json'});if(window.Capacitor?.isNativePlatform?.()&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Cadangan Ruang Hari'});return}catch(e){if(e.name==='AbortError')return}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}
function validData(d){return d&&Array.isArray(d.tasks)&&Array.isArray(d.journals)&&d.tasks.length<=5000&&d.journals.length<=5000&&d.tasks.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&t.title.length<=160&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&/^\d{2}:\d{2}$/.test(t.time)&&typeof t.done==='boolean'&&typeof t.remind==='boolean'&&['Personal','Belajar','Kerja','Kesehatan'].includes(t.category)&&['Normal','Tinggi','Rendah'].includes(t.priority))&&d.journals.every(j=>typeof j.id==='string'&&typeof j.title==='string'&&j.title.length<=120&&typeof j.body==='string'&&j.body.length<=20000&&/^\d{4}-\d{2}-\d{2}$/.test(j.date)&&typeof j.mood==='string')}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>5*1048576)throw Error();const d=JSON.parse(await input.files[0].text());if(!validData(d))throw Error();const next={tasks:[...state.tasks,...d.tasks.filter(t=>!state.tasks.some(x=>x.id===t.id))],journals:[...state.journals,...d.journals.filter(j=>!state.journals.some(x=>x.id===j.id))]};if(await commit(next)){let importedProfile=false;if(d.profile&&typeof d.profile.name==='string'&&d.profile.name.trim()&&d.profile.name.length<=40&&typeof d.profile.bio==='string'&&d.profile.bio.length<=120&&(!d.profile.photo||safePhoto(d.profile.photo))&&(d.profile.photo||'').length<200000){if(confirm('Data harian sudah diimpor. Gunakan juga nama dan foto profil dari cadangan?')){const nextProfile={name:d.profile.name.trim(),bio:d.profile.bio,photo:d.profile.photo||''};if(write('rh.profile',nextProfile)){localProfile=nextProfile;importedProfile=true}}}render();await scheduleNative();toast(importedProfile?'Cadangan dan profil berhasil diimpor.':'Cadangan harian berhasil ditambahkan.');}}catch{toast('Berkas cadangan tidak valid atau terlalu besar.')}};input.click()}
function openProfile(){const f=$('#profile-form');f.elements.name.value=localProfile.name;f.elements.bio.value=localProfile.bio||'';draftPhoto=localProfile.photo||'';$('#profile-preview').innerHTML=avatarHTML(draftPhoto,f.elements.name.value);$('#profile-error').textContent='';$('#profile-dialog').showModal()}
async function resizePhoto(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Pilih foto JPG, PNG, atau WebP.');if(file.size>8*1024*1024)throw Error('Ukuran foto maksimal 8 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);return canvas.toDataURL('image/webp',.82)}finally{bitmap.close()}}
$('#profile-photo-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const save=$('#profile-save');save.disabled=true;try{draftPhoto=await resizePhoto(file);$('#profile-preview').innerHTML=avatarHTML(draftPhoto,$('#profile-form').elements.name.value);$('#profile-error').textContent='';}catch(err){$('#profile-error').textContent=err.message}finally{save.disabled=false;e.target.value=''}});
$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target;const name=f.elements.name.value.trim(),bio=f.elements.bio.value.trim();if(!name){$('#profile-error').textContent='Nama tidak boleh kosong.';return}const next={name,bio,photo:draftPhoto};if(write('rh.profile',next)){localProfile=next;$('#profile-dialog').close();render();toast('Profil diperbarui. Selamat datang, '+name+'.')}});
$('#profile-form').elements.name.addEventListener('input',e=>{if(!draftPhoto)$('#profile-preview').innerHTML=avatarHTML('',e.target.value)});
const actions={'add-task':()=>openTask(),'add-journal':()=>openJournal(),'edit-profile':openProfile,'pick-photo':()=>$('#profile-photo-input').click(),'remove-photo':()=>{draftPhoto='';$('#profile-preview').innerHTML=avatarHTML('',$('#profile-form').elements.name.value)},upload:()=>$('#music-files').click(),play:playPause,previous:()=>playTrack((trackIndex-1+tracks.length)%tracks.length),next:()=>playTrack((trackIndex+1)%tracks.length),timer:toggleTimer,'timer-reset':async()=>{timerEnd=null;timerLeft=25*60;if(native)await native.cancel({notifications:[{id:2147483647}]});render()},notify:enableNotifications,export:exportData,import:importData};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.view)setView(b.dataset.view);if(b.dataset.action)await actions[b.dataset.action]?.();if(b.dataset.date){selectedDate=b.dataset.date;render()}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.editTask)openTask(b.dataset.editTask);if(b.dataset.editJournal)openJournal(b.dataset.editJournal);if(b.dataset.toggle){if(await commit({...state,tasks:state.tasks.map(t=>t.id===b.dataset.toggle?{...t,done:!t.done}:t)})){render();await scheduleNative();}}if(b.dataset.deleteTask&&confirm('Hapus tugas ini?')){if(await commit({...state,tasks:state.tasks.filter(t=>t.id!==b.dataset.deleteTask)})){render();await scheduleNative();}}if(b.dataset.deleteJournal&&confirm('Hapus cerita ini?')){if(await commit({...state,journals:state.journals.filter(j=>j.id!==b.dataset.deleteJournal)}))render()}if(b.dataset.track!==undefined){if(+b.dataset.track===trackIndex)await playPause();else await playTrack(+b.dataset.track)}if(b.dataset.deleteTrack!==undefined){let index=+b.dataset.deleteTrack,t=tracks[index];await storeTrack(t,true);if(index===trackIndex){audio.pause();audio.removeAttribute('src');lastSeek=0}URL.revokeObjectURL(t.url);tracks.splice(index,1);if(index<trackIndex)trackIndex--;trackIndex=Math.min(trackIndex,Math.max(0,tracks.length-1));if(tracks.length&&!audio.getAttribute('src'))audio.src=tracks[trackIndex].url;render()}}catch(err){toast(err.message||'Ada kendala. Coba lagi.')}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#task-search').focus();$('#task-search').setSelectionRange(pos,pos)}if(e.target.matches('.seek')&&audio.duration){audio.currentTime=+e.target.value/100*audio.duration;lastSeek=+e.target.value}});document.addEventListener('change',e=>{if(e.target.id==='schedule-date'){selectedDate=e.target.value||today;render()}});
$('#add-task').onclick=()=>view==='journal'?openJournal():view==='music'?$('#music-files').click():openTask();$('#profile').onclick=()=>setView('settings');$('#enable-notifications').onclick=enableNotifications;$('#bell').onclick=()=>{$('#inbox').innerHTML=inbox.length?inbox.map(n=>`<div class="inbox-item">${esc(n.title)}<small>${new Date(n.date).toLocaleString('id-ID')}</small></div>`).join(''):'<div class="empty">Belum ada pemberitahuan.<br>Pengingat tugasmu akan muncul di sini.</div>';$('#bell-dot').style.display='none';$('#inbox-dialog').showModal()};
async function boot(){ $('#today-label').textContent=dateText(today,{day:'numeric',month:'short',year:'numeric'});render();initMusic();if(window.Capacitor?.isNativePlatform?.()){try{const module=await import('./native.js');native=module.notifications;await native.createChannel({id:'daily-reminders',name:'Pengingat harian',importance:4});await scheduleNative()}catch{toast('Plugin Android belum siap. Periksa build APK.')}}setInterval(()=>{updateTimer();checkReminders();$('#clock').textContent=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})+' · WAKTU LOKAL'},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTimer();checkReminders()}})}boot();
